CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, username VARCHAR(40) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'student', status VARCHAR(20) NOT NULL DEFAULT 'active', moderator_board_id BIGINT NULL, points INT NOT NULL DEFAULT 0, school VARCHAR(100) DEFAULT '', grade VARCHAR(40) DEFAULT '', major VARCHAR(100) DEFAULT '', subject_preference VARCHAR(100) DEFAULT '', public_school BOOLEAN NOT NULL DEFAULT FALSE, public_grade BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at DATETIME NULL);
CREATE TABLE boards (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255) NOT NULL, sort_order INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'enabled');
CREATE TABLE tags (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(40) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'enabled');
CREATE TABLE posts (id BIGINT PRIMARY KEY AUTO_INCREMENT, board_id BIGINT NOT NULL, author_id BIGINT NOT NULL, type VARCHAR(20) NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, image_path VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'published', is_solved BOOLEAN NOT NULL DEFAULT FALSE, accepted_reply_id BIGINT, is_featured BOOLEAN NOT NULL DEFAULT FALSE, is_top BOOLEAN NOT NULL DEFAULT FALSE, view_count INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(board_id,status,created_at), INDEX(author_id), FOREIGN KEY(board_id) REFERENCES boards(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE post_tags (post_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(post_id,tag_id), FOREIGN KEY(post_id) REFERENCES posts(id), FOREIGN KEY(tag_id) REFERENCES tags(id));
CREATE TABLE replies (id BIGINT PRIMARY KEY AUTO_INCREMENT, post_id BIGINT NOT NULL, author_id BIGINT NOT NULL, content TEXT NOT NULL, image_path VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'published', is_accepted BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(post_id,status), FOREIGN KEY(post_id) REFERENCES posts(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE favorites (user_id BIGINT NOT NULL, post_id BIGINT NOT NULL, PRIMARY KEY(user_id,post_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, kind VARCHAR(30) NOT NULL, message VARCHAR(255) NOT NULL, post_id BIGINT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,is_read), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE reports (id BIGINT PRIMARY KEY AUTO_INCREMENT, reporter_id BIGINT NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, reason VARCHAR(40) NOT NULL, description VARCHAR(500) DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'pending', handler_id BIGINT, handle_note VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, handled_at DATETIME, INDEX(status,created_at), FOREIGN KEY(reporter_id) REFERENCES users(id));
CREATE TABLE point_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, action VARCHAR(30) NOT NULL, points INT NOT NULL, balance_after INT NOT NULL, ref_type VARCHAR(20), ref_id BIGINT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE admin_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT NOT NULL, action VARCHAR(40) NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, detail VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
